"""ex01 ReAct 循环骨架（stub 工具 + 脚本化 LLM，离线可跑）。"""

TOOLS = {
    "lookup": lambda key: {
        "cn_population": "1411780000",
        "fr_capital": "Paris",
    }.get(key, "NOT_FOUND"),
    "add": lambda s: str(sum(int(x) for x in s.split(","))),
}

MAX_STEPS = 6

# 脚本化的「LLM」：真实场景由模型生成，这里用固定剧本保证输出可复现
SCRIPT = [
    ("Thought: 先查中国人口规模", "lookup", "cn_population"),
    ("Thought: 再查法国首都", "lookup", "fr_capital"),
    ("Thought: 用计算器验证 1200+3400", "add", "1200,3400"),
    ("Thought: 信息齐全，可以作答", "finish", "中国约14.12亿人; 法国首都巴黎; 1200+3400=4600"),
]


def react_loop(script, tools, max_steps):
    """ReAct 主循环：Thought -> Action -> Observation，直到 finish 或步数熔断。"""
    trace = []
    for i in range(max_steps):
        if i >= len(script):
            trace.append("Observation: 剧本耗尽，触发步数熔断")
            break
        thought, action, arg = script[i]
        trace.append(thought)
        trace.append("Action: %s[%s]" % (action, arg))
        if action == "finish":
            trace.append("Final Answer: %s" % arg)
            break
        trace.append("Observation: %s" % tools[action](arg))
    return trace


if __name__ == "__main__":
    tr = react_loop(SCRIPT, TOOLS, MAX_STEPS)
    for line in tr:
        print(line)
    print("Action 次数 = %d" % sum(1 for l in tr if l.startswith("Action:")))
